mapper.sql:
WHERE project_costings.status >= 0 AND project_costings.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})

  AND(
    project_costings.pc_code LIKE CONCAT("%", #{filter.searchText}, "%")
    OR boqs.code LIKE CONCAT("%", #{filter.searchText}, "%")
    OR customers.name LIKE CONCAT("%", #{filter.searchText}, "%")
    OR customer_contacts.contact_name LIKE CONCAT("%", #{filter.searchText}, "%")
    OR employees.name LIKE CONCAT("%", #{filter.searchText}, "%")
  )


  AND project_costings.date >= #{filter.dateFrom}


  AND project_costings.date <= #{filter.dateTo}


  AND project_costings.status = #{filter.status}


  AND project_costings.created_by = #{userId}

mapper.select:
SELECT
project_costings.total_amount * 100 / project_costings.total_sub_amount AS roi,



ORDER BY


    ${filter.orderBy}


    project_costings.date DESC, project_costings.date DESC, project_costings.id DESC



  LIMIT #{filter.page}, #{filter.rowsPerPage}
